def analyze(datasets):
    def pick(cols):
        return next((d for d in datasets if all(c in d.get('columns', []) for c in cols)), None)
    rev = pick(['period_start', 'revenue'])
    sep = pick(['product_name', 'sku', 'total_quantity', 'total_amount'])
    trend = pick(['month', 'total_amount', 'total_quantity'])
    sold = pick(['sku', 'product_name_en', 'units_sold'])
    stock = pick(['sku', 'product_name_en', 'stock_on_hand'])
    out = []
    if rev:
        rows = rev['rows']
        cur = next(r for r in rows if r['period_start'] == '2026-09-01')
        prev = next(r for r in rows if r['period_start'] == '2026-08-01')
        chg = (cur['revenue'] - prev['revenue']) / prev['revenue'] * 100
        out.append({'title': '销售额环比', 'detail': '2026年9月已确认销售额 %.2f，较8月 %.2f 变化 %.1f%%，基本持平。' % (cur['revenue'], prev['revenue'], chg), 'evidence': {'sep_revenue': cur['revenue'], 'aug_revenue': prev['revenue'], 'mom_pct': round(chg, 2)}})
    if sep:
        rows = sorted(sep['rows'], key=lambda r: -r['total_amount'])
        top = rows[0]
        tot = sum(r['total_amount'] for r in rows)
        out.append({'title': '9月畅销产品', 'detail': '9月采购金额最高的是 %s（%s），金额 %.2f，占当月采购总额 %.1f%%。' % (top['product_name'], top['sku'], top['total_amount'], top['total_amount'] / tot * 100), 'evidence': {'top_amount': top['total_amount'], 'top_share_pct': round(top['total_amount'] / tot * 100, 1), 'sku_count': len(rows)}})
    if trend:
        rows = sorted(trend['rows'], key=lambda r: r['month'])
        last = rows[-1]
        prev = rows[-2]
        out.append({'title': '采购趋势', 'detail': '2026年9月采购金额 %.2f、采购箱数 %.0f，较8月金额增长 %.1f%%，为近六个月最高。' % (last['total_amount'], last['total_quantity'], (last['total_amount'] - prev['total_amount']) / prev['total_amount'] * 100), 'evidence': {'sep_amount': last['total_amount'], 'sep_qty': last['total_quantity'], 'aug_amount': prev['total_amount']}})
    if sold and stock:
        s = {r['sku']: r for r in sold['rows']}
        for r in stock['rows']:
            if r['sku'] in s:
                days = r['stock_on_hand'] / (s[r['sku']]['units_sold'] / 30)
                out.append({'title': '库存可售天数', 'detail': '%s（%s）期末库存 %.0f，按9月销量 %.0f 估算仅可售 %.1f 天，需尽快补货。' % (r['product_name_en'], r['sku'], r['stock_on_hand'], s[r['sku']]['units_sold'], days), 'evidence': {'stock': r['stock_on_hand'], 'units_sold': s[r['sku']]['units_sold'], 'days_cover': round(days, 1)}})
    return out
